import React, { useState, useCallback, useEffect, useRef } from 'react';
import { SeafoodInputItem, SeafoodResultItem, Rating, UploadSummary } from './types';
import { rateSeafoodData, analyzeSheetLayout, updateAnalysisForId } from './services/geminiService';
import { loadDatabaseFromUrl } from './services/referenceDatabase';
import { getUploadHistory, saveUploadToHistory } from './services/historyService';
import { performDataAudit, AuditReport } from './services/dataAuditService';
import Header from './components/Header';
import FileUpload from './components/FileUpload';
import ResultsTable from './components/ResultsTable';
import Loader from './components/Loader';
import Dashboard from './components/Dashboard';
import ColumnMapper from './components/ColumnMapper';
import DataPreview from './components/DataPreview';
import ChartsView from './components/ChartsView';
import Modal from './components/Modal';
import DataQualityAudit from './components/DataQualityAudit';

// This declaration is necessary because the library is loaded from a script tag in index.html
declare var XLSX: any;

type View = 'dashboard' | 'analyzer';
type AnalyzerState = 'upload' | 'preview' | 'mapping' | 'audit' | 'loading' | 'results';
type ResultsViewMode = 'table' | 'charts';

const MAPPABLE_FIELDS = [
  'Wild or Farmed',
  'Common name',
  'Scientific name',
  'Source country',
  'Body of water',
  'Production Method',
  'Certification',
  'Supplier',
  'Product Name',
  'Volume',
];

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [analyzerState, setAnalyzerState] = useState<AnalyzerState>('upload');
  const [results, setResults] = useState<SeafoodResultItem[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  // State for raw data and headers
  const [originalData, setOriginalData] = useState<SeafoodInputItem[] | null>(null);
  const [originalHeaders, setOriginalHeaders] = useState<string[]>([]);
  const [currentFileName, setCurrentFileName] = useState<string>('');

  // State for column mapping and display-optimized results
  const [columnMapping, setColumnMapping] = useState<Record<string, string>>({});
  const [displayResults, setDisplayResults] = useState<any[] | null>(null);
  const [displayHeaders, setDisplayHeaders] = useState<string[]>([]);
  const [visibleColumns, setVisibleColumns] = useState<Set<string>>(new Set());
  const [auditReport, setAuditReport] = useState<AuditReport | null>(null);


  // State for preview step
  const [workbook, setWorkbook] = useState<any>(null); // XLSX workbook object
  const [sheetNames, setSheetNames] = useState<string[]>([]);
  const [selectedSheet, setSelectedSheet] = useState<string>('');
  const [headerRowIndex, setHeaderRowIndex] = useState<number>(1);
  const [previewData, setPreviewData] = useState<(string|number)[][]>([]);
  const [isPreviewLoading, setIsPreviewLoading] = useState<boolean>(false);
  const [previewWarning, setPreviewWarning] = useState<string | null>(null);


  const [uploadHistory, setUploadHistory] = useState<UploadSummary[]>([]);
  const [progress, setProgress] = useState<{ processed: number; total: number } | null>(null);

  // State for results view
  const [resultsViewMode, setResultsViewMode] = useState<ResultsViewMode>('table');
  const [activeFilter, setActiveFilter] = useState<{title: string; data: any[]} | null>(null);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);
  const [modalFilterData, setModalFilterData] = useState<{title: string; data: SeafoodResultItem[]} | null>(null);

  const analysisAbortController = useRef<AbortController | null>(null);


  useEffect(() => {
    // Load history on initial mount
    setUploadHistory(getUploadHistory());

    // Attempt to load the full database from the root/public folder.
    loadDatabaseFromUrl('seafood-watch-data.csv');
  }, []);

  const resetAnalyzerState = () => {
    setResults(null);
    setDisplayResults(null);
    setDisplayHeaders([]);
    setError(null);
    setOriginalData(null);
    setOriginalHeaders([]);
    setCurrentFileName('');
    setProgress(null);
    setWorkbook(null);
    setSheetNames([]);
    setSelectedSheet('');
    setHeaderRowIndex(1);
    setPreviewData([]);
    setColumnMapping({});
    setAuditReport(null);
    setVisibleColumns(new Set());
    setResultsViewMode('table');
    setActiveFilter(null);
    setIsFilterModalOpen(false);
    setModalFilterData(null);
    setAnalyzerState('upload');
    setIsPreviewLoading(false);
    setPreviewWarning(null);
    analysisAbortController.current = null;
  };

  const generatePreviewData = (worksheet: any) => {
    const previewJson: (string|number)[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', raw: false, blankrows: false });
    setPreviewData(previewJson.slice(0, 15)); // Preview first 15 rows
  };

  const handleProcessFile = useCallback(async (file: File) => {
    resetAnalyzerState();
    setAnalyzerState('preview');
    setIsPreviewLoading(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = e.target?.result;
        if (!data) throw new Error("File data could not be read.");

        let wb: any;
        try {
          wb = XLSX.read(data, { type: 'binary', cellNF: false, cellText: false });
        } catch (parseError) {
          console.error("File parsing error:", parseError);
          throw new Error("Could not parse file. Please ensure it is a valid, uncorrupted XLSX or CSV file.");
        }

        const names = wb.SheetNames;
        if (names.length === 0) {
          throw new Error("The uploaded file is empty or contains no sheets.");
        }

        setWorkbook(wb);
        setSheetNames(names);
        setCurrentFileName(file.name);

        let bestSheetName = names[0];
        let bestHeaderRow = 1;

        try {
          const sheetPreviews = names.map(name => {
            const ws = wb.Sheets[name];
            const sheetData = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false, blankrows: false }).slice(0, 15);
            return { sheetName: name, data: sheetData };
          });

          const layout = await analyzeSheetLayout(sheetPreviews);
          bestSheetName = layout.bestSheetName;
          bestHeaderRow = layout.bestHeaderRow;
        } catch (aiError) {
          console.warn("AI sheet analysis failed, falling back to default.", aiError);
          setPreviewWarning("AI analysis for sheet layout failed. We've selected the first sheet and header row as a default. Please verify the selections are correct.");
        }

        setSelectedSheet(bestSheetName);
        setHeaderRowIndex(bestHeaderRow);
        generatePreviewData(wb.Sheets[bestSheetName]);

      } catch (err: any) {
        console.error(err);
        setError(`Error processing file: ${err.message}`);
        setAnalyzerState('upload');
      } finally {
        setIsPreviewLoading(false);
      }
    };
    reader.onerror = () => {
      setError('There was an error reading the file. It may be too large or corrupted.');
      setAnalyzerState('upload');
      setIsPreviewLoading(false);
    }
    reader.readAsBinaryString(file);
  }, []);

  const handleSheetChange = (sheetName: string) => {
    if (workbook) {
      setSelectedSheet(sheetName);
      generatePreviewData(workbook.Sheets[sheetName]);
    }
  };

  const handleHeaderRowChange = (newRowIndex: number) => {
    setHeaderRowIndex(newRowIndex);
  };

  const handleConfirmPreview = useCallback(() => {
    setError(null);
    if (!workbook || !selectedSheet) {
        setError("Workbook data is missing. Please re-upload.");
        setAnalyzerState('upload');
        return;
    }

    try {
        const worksheet = workbook.Sheets[selectedSheet];
        const dataAsArray: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', blankrows: false });

        if (dataAsArray.length < headerRowIndex) {
            throw new Error(`Header row ${headerRowIndex} does not exist in the data.`);
        }

        const rawHeaders: string[] = dataAsArray[headerRowIndex - 1].map(header => String(header).trim());

        const headers: string[] = [];
        const counts: Record<string, number> = {};

        for (const header of rawHeaders) {
            if (!header) {
                headers.push('');
                continue;
            }

            counts[header] = (counts[header] || 0) + 1;

            if (counts[header] > 1) {
                let newHeader = `${header} (${counts[header]})`;
                while (rawHeaders.includes(newHeader) || headers.includes(newHeader)) {
                    counts[header]++;
                    newHeader = `${header} (${counts[header]})`;
                }
                headers.push(newHeader);
            } else {
                headers.push(header);
            }
        }

        const jsonData = dataAsArray.slice(headerRowIndex).map(row => {
            const rowObject: SeafoodInputItem = {};
            headers.forEach((header, index) => {
                if(header) {
                    rowObject[header] = row[index];
                }
            });
            return rowObject;
        }).filter(obj => Object.keys(obj).length > 0);

        if (jsonData.length === 0) {
          throw new Error("The selected sheet and header row result in no data to process.");
        }

        setOriginalData(jsonData);
        setOriginalHeaders(headers.filter(h => h));
        setAnalyzerState('mapping');

    } catch(err: any) {
        setError(`Error processing sheet: ${err.message}`);
    }
  }, [workbook, selectedSheet, headerRowIndex]);

  const handleConfirmMapping = useCallback((mapping: Record<string, string>) => {
    if (!originalData) {
        setError("Original data missing.");
        setAnalyzerState('upload');
        return;
    }
    setColumnMapping(mapping);

    // Perform Audit
    const report = performDataAudit(originalData, mapping);
    setAuditReport(report);
    setAnalyzerState('audit');

  }, [originalData]);

  const handleStartAnalysis = useCallback(async () => {
    if (!originalData) return;

    setAnalyzerState('loading');
    setError(null);

    analysisAbortController.current = new AbortController();

    try {
        // Filter out rows that don't have a Common Name
        const commonNameHeader = columnMapping['Common name'];
        let dataToProcess = originalData;

        if (commonNameHeader && commonNameHeader !== 'N/A') {
            dataToProcess = originalData.filter(row => {
                const val = row[commonNameHeader];
                return val !== undefined && val !== null && String(val).trim() !== '';
            });
        }

        setProgress({ processed: 0, total: dataToProcess.length });

        if (dataToProcess.length === 0) {
             throw new Error("No valid rows found to process. Please ensure your data has values in the 'Common name' column.");
        }

        const transformedData = dataToProcess.map(row => {
            const newRow: { [key: string]: string | number } = {};
            for (const mappableField of MAPPABLE_FIELDS) {
                const userColumnName = columnMapping[mappableField];
                if (userColumnName && userColumnName !== 'N/A' && row[userColumnName] !== undefined) {
                    newRow[mappableField] = row[userColumnName];
                }
            }
            return newRow;
        });

        const handleProgressUpdate = (processed: number, total: number) => {
          setProgress({ processed, total });
        };

        const analysisResults = await rateSeafoodData(transformedData, handleProgressUpdate, analysisAbortController.current.signal);

        const finalResults = dataToProcess.map((originalItem, index) => {
            const analysisPart = analysisResults[index];

            return {
                ...originalItem,
                uniqueId: analysisPart.uniqueId,
                matchedKDEs: analysisPart.matchedKDEs, 
                rating: analysisPart.rating,
                reliabilityScore: analysisPart.reliabilityScore,
                notes: analysisPart.notes,
            };
        });

        setResults(finalResults);

        const mappedHeaders = Object.values(columnMapping).filter(h => h && h !== 'N/A') as string[];
        const defaultVisible = new Set<string>([
            ...mappedHeaders,
            'uniqueId', 
            'rating', 
            'reliabilityScore'
        ]);

        setDisplayResults(finalResults);
        setDisplayHeaders(originalHeaders);
        setVisibleColumns(defaultVisible);

        const matchedCount = finalResults.filter(r => r.rating !== Rating.NA).length;
        const matchPercentage = finalResults.length > 0 ? (matchedCount / finalResults.length) * 100 : 0;
        const totalReliability = finalResults.reduce((acc, r) => acc + r.reliabilityScore, 0);
        const averageReliability = finalResults.length > 0 ? totalReliability / finalResults.length : 0;
        const ratingDistribution = finalResults.reduce<{[key in Rating]?: number}>((acc, item) => {
            acc[item.rating] = (acc[item.rating] || 0) + 1;
            return acc;
        }, {});

        const noteCounts = finalResults.reduce((acc, item) => {
          acc[item.notes] = (acc[item.notes] || 0) + 1;
          return acc;
        }, {} as { [key: string]: number });
        const commonIssues = Object.entries(noteCounts)
          .sort(([, countA], [, countB]) => (countB as number) - (countA as number))
          .slice(0, 5)
          .map(([issue, count]) => ({ issue, count: count as number }));

        const uploadSummaryData = {
            fileName: currentFileName, 
            rowCount: finalResults.length, 
            matchPercentage,
            averageReliability, 
            ratingDistribution, 
            commonIssues,
        };

        const newHistory = saveUploadToHistory(uploadSummaryData);
        setUploadHistory(newHistory);
        setAnalyzerState('results');

        // iFrame Communication Hook: Inform parent site that analysis is complete
        if (window.parent !== window) {
            window.parent.postMessage({
                type: 'SEAFOOD_ANALYSIS_COMPLETE',
                fileName: currentFileName,
                summary: uploadSummaryData
            }, '*');
        }

    } catch (err: any) {
        if (err.name === 'AbortError' || err.message.includes('aborted')) {
            console.log('Analysis was cancelled by the user.');
            return;
        }
        console.error(err);
        setError(`An error occurred during analysis: ${err.message}`);
        setAnalyzerState('audit'); 
    }
  }, [originalData, currentFileName, originalHeaders, columnMapping]);

  const handleCancelAnalysis = useCallback(() => {
    if (analysisAbortController.current) {
        analysisAbortController.current.abort();
    }
    setAnalyzerState('audit');
    setError(null);
  }, []);

  const handleUpdateResult = useCallback(async (index: number, newUniqueId: string) => {
     if (!results || !results[index]) return;

     const updatedResults = [...results];
     updatedResults[index] = { ...updatedResults[index], isUpdating: true, uniqueId: newUniqueId };
     setResults(updatedResults);
     setDisplayResults(updatedResults);

     try {
         const originalItem = updatedResults[index];
         const updatedAnalysis = await updateAnalysisForId(originalItem, newUniqueId);

         const finalResults = [...results];
         finalResults[index] = {
             ...originalItem,
             ...updatedAnalysis,
             isUpdating: false
         };

         setResults(finalResults);
         setDisplayResults(finalResults);

     } catch (err) {
         console.error("Failed to update result:", err);
         const revertedResults = [...results];
         revertedResults[index] = { ...revertedResults[index], isUpdating: false };
         setResults(revertedResults);
         setDisplayResults(revertedResults);
         setError("Failed to update the record. Please try again.");
     }
  }, [results]);

  const handleExport = useCallback(() => {
    if (!results || originalHeaders.length === 0) return;
    const headers = [...originalHeaders, 'Unique ID', 'Matched KDEs', 'Rating', 'Reliability Score', 'Notes'];
    const escapeCsv = (val: any): string => {
        if (val === undefined || val === null) return '';
        const str = String(val);
        if (str.includes(',') || str.includes('"') || str.includes('\n')) {
            return `"${str.replace(/"/g, '""')}"`;
        }
        return str;
    };
    const csvContent = [
        headers.join(','),
        ...results.map(row => {
            const originalValues = originalHeaders.map(header => escapeCsv(row[header]));
            const analysisValues = [
                escapeCsv(row.uniqueId), 
                escapeCsv(row.matchedKDEs),
                escapeCsv(row.rating), 
                escapeCsv(row.reliabilityScore), 
                escapeCsv(row.notes)
            ];
            return [...originalValues, ...analysisValues].join(',');
        })
    ].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    if (link.href) URL.revokeObjectURL(link.href);
    const url = URL.createObjectURL(blob);
    link.href = url;
    link.setAttribute('download', `${currentFileName.replace(/\.[^/.]+$/, "")}_analyzed.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [results, originalHeaders, currentFileName]);

  const handleChartSegmentClick = (title: string, data: SeafoodResultItem[]) => {
    setModalFilterData({ title, data });
    setIsFilterModalOpen(true);
  };
  const handleConfirmFilter = () => {
    if (modalFilterData) {
      setActiveFilter({ title: modalFilterData.title, data: modalFilterData.data });
      setResultsViewMode('table');
    }
    setIsFilterModalOpen(false);
  };
  const handleClearFilter = () => setActiveFilter(null);
  const handleCancelFilter = () => setIsFilterModalOpen(false);
  const handleVisibleColumnsChange = (newVisible: Set<string>) => {
    setVisibleColumns(newVisible);
  };
  const handleCancel = () => resetAnalyzerState();
  const handleReturnToPreview = () => { setOriginalData(null); setOriginalHeaders([]); setAnalyzerState('preview'); };
  const handleReturnToMapping = () => { setAnalyzerState('mapping'); }; 
  const handleAnalyzeNew = () => { resetAnalyzerState(); setView('analyzer'); };
  const handleReturnToDashboard = () => { resetAnalyzerState(); setView('dashboard'); };

  const renderContent = () => {
    if (view === 'dashboard') {
      return (
          <div className="animate-fade-in-up">
              <Dashboard history={uploadHistory} onAnalyzeNew={handleAnalyzeNew} />
          </div>
      );
    }

    return (
      <div className="animate-fade-in-up" key={analyzerState}>
        {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative my-6 max-w-4xl mx-auto" role="alert">
            <strong className="font-bold">Error:</strong><span className="block sm:inline ml-2">{error}</span>
            </div>
        )}
        {analyzerState === 'upload' && <FileUpload onProcessFile={handleProcessFile} isLoading={false} />}
        {analyzerState === 'preview' && <DataPreview isAnalyzing={isPreviewLoading} sheetNames={sheetNames} selectedSheet={selectedSheet} onSheetChange={handleSheetChange} headerRowIndex={headerRowIndex} onHeaderRowChange={handleHeaderRowChange} previewData={previewData} onConfirm={handleConfirmPreview} onCancel={handleCancel} warning={previewWarning}/>}
        {analyzerState === 'mapping' && originalHeaders.length > 0 && <ColumnMapper fileHeaders={originalHeaders} mappableFields={MAPPABLE_FIELDS} onConfirm={handleConfirmMapping} onCancel={handleReturnToPreview}/>}
        {analyzerState === 'audit' && auditReport && <DataQualityAudit report={auditReport} onConfirm={handleStartAnalysis} onBack={handleReturnToMapping} />}
        {analyzerState === 'loading' && <Loader progress={progress} onCancel={handleCancelAnalysis} />}
        {analyzerState === 'results' && results && displayResults && (
          <div className="flex flex-col items-center space-y-6">
            <div 
              className="flex justify-center p-1 bg-gray-200 rounded-lg"
              role="tablist"
              aria-label="Result view modes"
            >
              <button 
                id="tab-table"
                role="tab"
                aria-selected={resultsViewMode === 'table'}
                aria-controls="tabpanel-table"
                onClick={() => setResultsViewMode('table')} 
                className={`px-4 py-2 text-sm font-semibold rounded-md transition-colors ${resultsViewMode === 'table' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>
                  Table
              </button>
              <button 
                id="tab-charts"
                role="tab"
                aria-selected={resultsViewMode === 'charts'}
                aria-controls="tabpanel-charts"
                onClick={() => setResultsViewMode('charts')} 
                className={`px-4 py-2 text-sm font-semibold rounded-md transition-colors ${resultsViewMode === 'charts' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>
                  Charts
              </button>
            </div>

            <div className="w-full max-w-7xl">
              {resultsViewMode === 'table' ? (
                 <div id="tabpanel-table" role="tabpanel" aria-labelledby="tab-table">
                    <ResultsTable 
                        results={activeFilter ? activeFilter.data : displayResults} 
                        originalHeaders={displayHeaders} 
                        columnMapping={columnMapping}
                        onExport={handleExport}
                        filterTitle={activeFilter?.title}
                        onClearFilter={handleClearFilter}
                        visibleColumns={visibleColumns}
                        onVisibleColumnsChange={handleVisibleColumnsChange}
                        onUpdateResult={handleUpdateResult}
                    />
                 </div>
              ) : (
                <div id="tabpanel-charts" role="tabpanel" aria-labelledby="tab-charts">
                    <ChartsView 
                        results={results} 
                        columnMapping={columnMapping} 
                        onSegmentClick={handleChartSegmentClick}
                    />
                </div>
              )}
            </div>

            <button onClick={handleReturnToDashboard} className="px-6 py-2 font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b] focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#00629B] transition-colors duration-200">Back to Dashboard</button>
          </div>
        )}
         <Modal 
            isOpen={isFilterModalOpen} 
            onClose={handleCancelFilter} 
            onConfirm={handleConfirmFilter}
            title="View Filtered Data"
         >
            <p>Would you like to see the {modalFilterData?.data.length} items for "{modalFilterData?.title}" in the data table?</p>
         </Modal>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 font-sans">
      <Header />
      <main className="container mx-auto p-4 sm:p-6 md:p-8">
        {renderContent()}
      </main>
      <footer className="text-center py-4 text-gray-500 text-sm">
        <p>&copy; {new Date().getFullYear()} Monterey Bay Aquarium Seafood Watch Program</p>
      </footer>
    </div>
  );
};

export default App;
